mapper.update:
UPDATE round_history rh
INNER JOIN weekly_settlements ws
  ON ws.round_id = rh.round_id
 AND ws.user_id = rh.user_id
SET rh.success_count = rh.success_count + 1
WHERE rh.round_id = #{roundId}
  AND ws.week_no = #{weekNo}
  AND ws.approved_post_count >= #{minCount}

UPDATE group_users gu
INNER JOIN weekly_settlements ws
  ON ws.user_id = gu.user_id
SET gu.streak_count = gu.streak_count + 1
WHERE gu.group_id = #{groupId}
  AND ws.round_id = #{roundId}
  AND ws.week_no = #{weekNo}
  AND ws.approved_post_count >= #{minCount}
